#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn tropical_fish_pattern_catalog_preserves_sparse_ids_names_and_kob_fallback() {
        assert_eq!(VANILLA_TROPICAL_FISH_PATTERNS.len(), 12);
        let mut ids = HashSet::new();
        let mut names = HashSet::new();
        for entry in VANILLA_TROPICAL_FISH_PATTERNS {
            assert!(ids.insert(entry.packed_id));
            assert!(names.insert(entry.serialized_name));
        }
        assert_eq!(
            vanilla_tropical_fish_pattern(257).serialized_name,
            "stripey"
        );
        assert_eq!(vanilla_tropical_fish_pattern(9999).constant_name, "KOB");
        assert_eq!(vanilla_tropical_fish_pattern(1281).base_id, 1);
        assert_eq!(vanilla_tropical_fish_pattern(1281).pattern_index, 5);
        assert_eq!(
            vanilla_tropical_fish_pattern_for_name("spotty").map(|entry| entry.packed_id),
            Some(1280)
        );
        assert_eq!(vanilla_tropical_fish_pattern_for_name("missing"), None);
        assert_eq!(VANILLA_TROPICAL_FISH_COMMON_VARIANTS.len(), 22);
        assert_eq!(
            VANILLA_TROPICAL_FISH_COMMON_VARIANTS[0],
            TropicalFishCommonVariantDescriptor {
                pattern_packed_id: 257,
                base_color_id: 1,
                pattern_color_id: 7
            }
        );
        assert_eq!(
            VANILLA_TROPICAL_FISH_COMMON_VARIANTS[21],
            TropicalFishCommonVariantDescriptor {
                pattern_packed_id: 1,
                base_color_id: 4,
                pattern_color_id: 4
            }
        );
    }

    fn starts_with_numeric_or_optional_numeric(value: &str) -> bool {
        let value = value.strip_prefix("Some(").unwrap_or(value);
        let mut characters = value.chars();
        let Some(first) = characters.next() else {
            return false;
        };
        first.is_ascii_digit()
            || (first == '-'
                && characters
                    .next()
                    .is_some_and(|character| character.is_ascii_digit()))
    }

    fn contains_numeric_tropical_fish_pattern_reference(
        source: &str,
        include_dialog_value_id: bool,
    ) -> bool {
        let compact: String = source
            .chars()
            .filter(|character| !character.is_whitespace())
            .collect();
        let numeric_construction =
            compact
                .match_indices("tropical_fish_pattern_id:")
                .any(|(offset, _)| {
                    starts_with_numeric_or_optional_numeric(
                        &compact[offset + "tropical_fish_pattern_id:".len()..],
                    )
                });
        let numeric_reference =
            compact
                .match_indices(".tropical_fish_pattern_id")
                .any(|(offset, _)| {
                    let suffix = &compact[offset + ".tropical_fish_pattern_id".len()..];
                    [",", "==", "!=", "="].iter().any(|separator| {
                        suffix
                            .strip_prefix(separator)
                            .is_some_and(starts_with_numeric_or_optional_numeric)
                    })
                });
        let numeric_dialog_value_id = include_dialog_value_id
            && compact.match_indices("value_id:").any(|(offset, _)| {
                starts_with_numeric_or_optional_numeric(&compact[offset + "value_id:".len()..])
            });
        numeric_construction || numeric_reference || numeric_dialog_value_id
    }

    #[test]
    fn numeric_tropical_fish_pattern_guard_covers_semantic_fixtures() {
        assert!(contains_numeric_tropical_fish_pattern_reference(
            "tropical_fish_pattern_id: Some(257),",
            false
        ));
        assert!(contains_numeric_tropical_fish_pattern_reference(
            "assert_eq!(patch.tropical_fish_pattern_id, Some(1));",
            false
        ));
        assert!(contains_numeric_tropical_fish_pattern_reference(
            "value_id: 1,",
            true
        ));
        assert!(!contains_numeric_tropical_fish_pattern_reference(
            "value_id: 1,",
            false
        ));
        assert!(!contains_numeric_tropical_fish_pattern_reference(
            "tropical_fish_pattern_id: Some(VANILLA_TROPICAL_FISH_PATTERN_STRIPEY_PACKED_ID),",
            false
        ));
        assert!(!contains_numeric_tropical_fish_pattern_reference("assert_eq!(patch.tropical_fish_pattern_id, Some(VANILLA_TROPICAL_FISH_PATTERN_FLOPPER_PACKED_ID));", false));
    }

    #[test]
    fn semantic_fixtures_do_not_restore_numeric_tropical_fish_pattern_ids() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                let include_dialog_value_id = path
                    .to_string_lossy()
                    .ends_with("/bbb-world/src/client/dialog/body.rs");
                if contains_numeric_tropical_fish_pattern_reference(
                    &source,
                    include_dialog_value_id,
                ) {
                    violations.push(path.display().to_string());
                }
            }
        }
        let mut violations = Vec::new();
        let crates = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap();
        for directory in [
            "bbb-native/src",
            "bbb-world/src",
            "bbb-net/src",
            "bbb-item-model/src",
            "bbb-renderer/src",
        ] {
            visit(&crates.join(directory), &mut violations);
        }
        assert!(
            violations.is_empty(),
            "numeric tropical fish pattern ids: {violations:?}"
        );
    }

    #[test]
    fn production_sources_do_not_redeclare_tropical_fish_pattern_facts() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/tropical_fish_patterns.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                let production = source.split("#[cfg(test)]").next().unwrap_or(&source);
                if production.contains("fn debug_tropical_fish_pattern_name")
                    || production.contains("const TROPICAL_FISH_PATTERNS:")
                {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel tropical fish pattern owners: {violations:?}"
        );
    }
}
